void weekend_due_date_moves_to_the_next_monday_for_the_fee() {
    // 2026-01-03(토) 대출, 기한 2026-01-17(토). 기한 자체는 그대로 두고 연체료만 월요일까지로 본다.
    Loan saturdayDue = Loan.reconstitute(UUID.randomUUID(), UUID.randomUUID(), UUID.randomUUID(),
            LocalDate.of(2026, 1, 3), LocalDate.of(2026, 1, 17), null);
    saturdayDue.returnBook(LocalDate.of(2026, 1, 19));
    assertThat(saturdayDue.getDueAt()).isEqualTo(LocalDate.of(2026, 1, 17));
    assertThat(saturdayDue.lateFee()).isZero();

    saturdayDue = Loan.reconstitute(UUID.randomUUID(), UUID.randomUUID(), UUID.randomUUID(),
            LocalDate.of(2026, 1, 3), LocalDate.of(2026, 1, 17), null);
    saturdayDue.returnBook(LocalDate.of(2026, 1, 20));
    assertThat(saturdayDue.lateFee()).isEqualTo(100);

    // 일요일 기한(2026-01-18)도 다음 월요일(2026-01-19)까지는 0원이다.
    Loan sundayDue = Loan.reconstitute(UUID.randomUUID(), UUID.randomUUID(), UUID.randomUUID(),
            LocalDate.of(2026, 1, 4), LocalDate.of(2026, 1, 18), null);
    sundayDue.returnBook(LocalDate.of(2026, 1, 19));
    assertThat(sundayDue.lateFee()).isZero();
}

